// Calculate sum of items
const items = JSON.parse($input.first().json.text).items; // The array from your AI agent
let calculatedSum = 0;

for (const item of items) {
    calculatedSum += item.total_price;
}

// Extract the total found on the receipt (ensure this is passed through)
const receiptTotal = JSON.parse($input.first().json.text).receipt_total; 

// Floating point math can be tricky (e.g., 0.1 + 0.2 != 0.3)
// Check if difference is less than 0.01 (1 cent)
const isVerified = Math.abs(calculatedSum - receiptTotal) < 0.01;

return {
    is_verified: isVerified,
    calculated_sum: parseFloat(calculatedSum.toFixed(2)),
    receipt_total: receiptTotal,
    difference: parseFloat((receiptTotal - calculatedSum).toFixed(2))
};

// Map through all binary keys and create a separate item for each
return Object.keys(items[0].binary).map(key => {
  return {
    json: { fileName: key }, // Keeps the original filename for reference
    binary: { 
      // Put the specific binary file into a consistent property name 'ocr_image'
      ocr_image: items[0].binary[key] 
    }
  };
});

// This takes the 'text' field from all incoming items 
// and joins them together into one single string.
const allText = items.map(item => item.json.text).join('\n\n--- New Image ---\n\n');

return {
  combinedText: allText
};
